{"policy":"permit (
    principal is User,
    action == Action::"readDocument",
    resource is Document
)
when {
    principal.isAnalyst || principal.isOfficer
};

forbid (
    principal is User,
    action == Action::"readDocument",
    resource is Document
)
when {
    (principal.isAnalyst || principal.isOfficer) &&
    !context.fromIntranet
};

forbid (
    principal is User,
    action == Action::"readDocument",
    resource is Document
)
when {
    (principal.isAnalyst || principal.isOfficer) &&
    resource.compartments.contains(context.relevantCompartment) &&
    principal.clearance < resource.classification
};"}
